<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { management } from '../api/management';
import { useRoute } from 'vue-router';
const libraryId=String(useRoute().params.libraryId);
const libraryTitle=ref('');
import type { TeacherProblem } from '../api/types';
import AsyncState from '../components/AsyncState.vue';
import { blankJudgeTemplate, functionProblemError, languageLabel, problemLanguage } from '../lib/problemCode';
const rows = ref<TeacherProblem[]>([]); const loading = ref(true); const error = ref(''); const query = ref(''); const editing = ref<TeacherProblem>(); const open = ref(false); const saving = ref(false); const tab = ref('public');
const visible = computed(() => rows.value.filter(p => p.title.includes(query.value)));
async function load() { loading.value = true; error.value = ''; try { const library=await management.library(libraryId); rows.value=library.problems; libraryTitle.value=library.title; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
function edit(p?: TeacherProblem) { editing.value = p ? { problemType: 'PROGRAM', language: 'C17', functionSignature: '', starterCode: '', judgeTemplate: '', ...JSON.parse(JSON.stringify(p)) } : { id: '', versionId: '', title: '', statement: '', inputDescription: '', outputDescription: '', samples: [], problemType: 'PROGRAM', language: 'C17', functionSignature: '', starterCode: '', judgeTemplate: '', referenceAnswer: '', testCases: [], maxScore: 20, timeLimitMs: 1000, memoryLimitMb: 128, codeLimitBytes: 16384, state: 'DRAFT' }; tab.value = 'public'; open.value = true; }
async function save() { if (!editing.value?.title.trim()) return ElMessage.warning('请填写标题'); const validation = functionProblemError(editing.value, true); if (validation) return ElMessage.warning(validation); saving.value = true; try { await management.saveLibraryProblem(libraryId, { ...editing.value, judgeTemplate: editing.value.problemType === 'FUNCTION' ? editing.value.judgeTemplate : '' }); open.value = false; ElMessage.success('已保存为草稿'); await load(); } catch (e) { ElMessage.error((e as Error).message); } finally { saving.value = false; } }
onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><div><RouterLink to="/teacher/problems" class="back-link">← 返回题库</RouterLink><h1>{{libraryTitle || '题目管理'}}</h1></div><div class="action-group"><RouterLink to="/teacher/import"><el-button>批量导入</el-button></RouterLink><el-button type="primary" @click="edit()">＋ 新建题目</el-button></div></div><div class="section-bar"><h2>全部题目 <span>{{ rows.length }}</span></h2><el-input v-model="query" placeholder="搜索题目标题" clearable class="search-input" /></div><AsyncState :loading="loading" :error="error" :empty="!visible.length" empty-text="题库暂无题目，可新建或批量导入。" @retry="load"><div class="panel table-panel"><el-table :data="visible"><el-table-column label="题目" min-width="240"><template #default="{ row }"><strong>{{ row.title }}</strong><small class="cell-subtitle">{{ languageLabel(problemLanguage(row)) }} · {{ row.problemType === 'FUNCTION' ? '函数题' : '完整程序题' }}</small></template></el-table-column><el-table-column prop="maxScore" label="分值" width="90" /><el-table-column label="限制" width="180"><template #default="{ row }">{{ row.timeLimitMs }} ms / {{ row.memoryLimitMb }} MB</template></el-table-column><el-table-column label="状态" width="130"><template #default="{ row }"><el-tag :type="row.state === 'DRAFT' ? 'info' : 'success'">{{ row.state === 'DRAFT' ? '草稿' : '已发布' }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">编辑题目</el-button></template></el-table-column></el-table></div></AsyncState><el-dialog v-model="open" :title="editing?.id ? '编辑题目草稿' : '新建题目'" width="820px" :close-on-click-modal="false"><el-form v-if="editing" label-position="top"><el-form-item label="题目标题"><el-input v-model="editing.title" maxlength="200" /></el-form-item><div class="two-column"><el-form-item label="题目类型"><el-select v-model="editing.problemType"><el-option label="完整程序题" value="PROGRAM" /><el-option label="函数题" value="FUNCTION" /></el-select></el-form-item><el-form-item label="编译语言"><el-select v-model="editing.language"><el-option label="C · GCC" value="C17" /><el-option label="C++ · G++" value="CPP17" /></el-select></el-form-item></div><el-tabs v-model="tab"><el-tab-pane label="学生可见内容" name="public"><el-form-item v-if="editing.problemType === 'FUNCTION'" label="函数接口（学生可见，发布前必填）"><el-input v-model="editing.functionSignature" type="textarea" :rows="3" class="mono-input" placeholder="填写函数声明、参数含义和返回值要求。" /></el-form-item><el-form-item label="起始代码（学生可见，可选）"><el-input v-model="editing.starterCode" type="textarea" :rows="5" class="mono-input" :placeholder="editing.problemType === 'FUNCTION' ? '只填写函数骨架和必要声明，不放参考实现或教师评测代码。' : '留空时使用对应语言的默认 main 模板。'" /></el-form-item><el-form-item label="题干"><el-input v-model="editing.statement" type="textarea" :rows="5" /></el-form-item><div class="two-column"><el-form-item label="输入格式"><el-input v-model="editing.inputDescription" type="textarea" :rows="3" /></el-form-item><el-form-item label="输出格式"><el-input v-model="editing.outputDescription" type="textarea" :rows="3" /></el-form-item></div><div v-for="(sample, i) in editing.samples" :key="i" class="two-column"><el-form-item :label="`样例 ${i + 1} 输入`"><el-input v-model="sample.input" type="textarea" /></el-form-item><el-form-item :label="`样例 ${i + 1} 输出`"><el-input v-model="sample.output" type="textarea" /></el-form-item></div><el-button @click="editing.samples.push({ input: '', output: '' })">＋ 添加公开样例</el-button></el-tab-pane><el-tab-pane label="教师私有内容" name="private"><el-alert title="参考答案、评测主程序与测试数据仅供授权教职工查看。" type="info" :closable="false" /><div v-if="editing.problemType === 'FUNCTION'" class="judge-template-section"><el-form-item label="教师评测主程序（私有，发布前必填）"><el-input v-model="editing.judgeTemplate" type="textarea" :rows="9" class="mono-input" placeholder="在调用被测函数的主程序中，用唯一占位符插入学生代码。" /></el-form-item><p class="muted">在学生代码插入处填写一次 <code>/*__STUDENT_CODE__*/</code>。</p><el-button size="small" :disabled="!!editing.judgeTemplate.trim()" @click="editing.judgeTemplate = blankJudgeTemplate(editing.language)">填入空白框架</el-button></div><el-form-item :label="editing.problemType === 'FUNCTION' ? '参考答案（函数实现，私有）' : '参考答案（完整程序，私有）'"><el-input v-model="editing.referenceAnswer" type="textarea" :rows="8" class="mono-input" /></el-form-item><div v-for="(test, i) in editing.testCases" :key="i" class="test-editor"><h3>测试点 {{ i + 1 }}</h3><div class="two-column"><el-input :model-value="test.input ?? ''" @update:model-value="test.input = $event" type="textarea" placeholder="输入" /><el-input :model-value="test.expectedOutput ?? ''" @update:model-value="test.expectedOutput = $event" type="textarea" placeholder="预期输出" /></div><div class="action-group mt"><el-select v-model="test.visibility" style="width:140px"><el-option label="隐藏用例" value="HIDDEN" /><el-option label="公开用例" value="PUBLIC" /></el-select><el-select v-model="test.comparisonMode" style="width:150px"><el-option label="精确比较" value="EXACT" /><el-option label="按空白分词" value="TOKENS" /></el-select><el-input-number :model-value="test.score ?? undefined" @update:model-value="test.score = $event ?? null" :min="0" :max="editing.maxScore" /></div></div><el-button @click="editing.testCases.push({ input: '', expectedOutput: '', score: null, visibility: 'HIDDEN', comparisonMode: 'EXACT' })">＋ 添加测试点</el-button></el-tab-pane><el-tab-pane label="分值与限制" name="limits"><el-form-item label="满分"><el-input-number v-model="editing.maxScore" :min="1" :max="1000" /></el-form-item><el-form-item label="运行时间（毫秒）"><el-input-number v-model="editing.timeLimitMs" :min="100" :max="10000" :step="100" /></el-form-item><el-form-item label="内存（MB）"><el-input-number v-model="editing.memoryLimitMb" :min="16" :max="512" :step="16" /></el-form-item></el-tab-pane></el-tabs></el-form><template #footer><el-button @click="open = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></template></el-dialog></div></template>

<style scoped>
.judge-template-section{padding:18px 0;margin-bottom:20px;border-bottom:1px solid #e8eef0}.judge-template-section p{margin:8px 0 12px}.judge-template-section .el-form-item{margin-bottom:8px}
</style>
